from flask import Flask, request, jsonify
import ldap
import re
import logging

app = Flask(__name__)
logging.basicConfig(level=logging.INFO)

LDAP_SERVER = "ldap://directory.internal.corp:389"
LDAP_BASE_DN = "dc=corp,dc=internal"
LDAP_BIND_DN = "cn=svc-webapp,ou=services,dc=corp,dc=internal"
LDAP_BIND_PW = "s3rv1c3_@cc0unt_pw"

def get_ldap_connection():
    conn = ldap.initialize(LDAP_SERVER)
    conn.simple_bind_s(LDAP_BIND_DN, LDAP_BIND_PW)
    return conn

def sanitize_display_name(name):
    """Sanitize display name for XSS prevention in responses."""
    return re.sub(r'[<>"\']', '', name)

@app.route('/api/v2/directory/lookup', methods=['POST'])
def directory_lookup():
    """Look up employee by username in corporate directory."""
    data = request.get_json()
    if not data or 'username' not in data:
        return jsonify({'error': 'username field required'}), 400

    username = data['username']

    # Input validation: alphanumeric and common chars only
    # Note: allows dots, hyphens, underscores for valid usernames like j.smith-ext
    if not re.match(r'^[a-zA-Z0-9._\-@]+$', username):
        logging.warning(f"Invalid characters in username lookup: {username[:50]}")
        return jsonify({'error': 'Invalid username format'}), 400

    if len(username) > 128:
        return jsonify({'error': 'Username too long'}), 400

    try:
        conn = get_ldap_connection()
        # Search for user in directory
        search_filter = f"(|(uid={username})(mail={username}))"
        results = conn.search_s(
            LDAP_BASE_DN,
            ldap.SCOPE_SUBTREE,
            search_filter,
            ['cn', 'mail', 'department', 'title', 'telephoneNumber']
        )
        conn.unbind_s()

        if not results:
            return jsonify({'found': False, 'message': 'User not found'}), 404

        entries = []
        for dn, attrs in results:
            if dn is None:
                continue
            entry = {
                'dn': dn,
                'name': sanitize_display_name(attrs.get('cn', [b''])[0].decode('utf-8')),
                'email': attrs.get('mail', [b''])[0].decode('utf-8'),
                'department': attrs.get('department', [b''])[0].decode('utf-8'),
                'title': attrs.get('title', [b''])[0].decode('utf-8'),
                'phone': attrs.get('telephoneNumber', [b''])[0].decode('utf-8')
            }
            entries.append(entry)

        return jsonify({'found': True, 'count': len(entries), 'results': entries}), 200

    except ldap.LDAPError as e:
        logging.error(f"LDAP error during lookup: {e}")
        return jsonify({'error': 'Directory service unavailable'}), 503

@app.route('/api/v2/directory/search', methods=['GET'])
def directory_search():
    """Search directory by partial name match."""
    query = request.args.get('q', '')

    if not query or len(query) < 2:
        return jsonify({'error': 'Query must be at least 2 characters'}), 400

    if len(query) > 64:
        return jsonify({'error': 'Query too long'}), 400

    # Basic wildcard search - allows partial matching
    try:
        conn = get_ldap_connection()
        search_filter = f"(cn=*{query}*)"
        results = conn.search_s(
            LDAP_BASE_DN,
            ldap.SCOPE_SUBTREE,
            search_filter,
            ['cn', 'mail', 'department']
        )
        conn.unbind_s()

        entries = []
        for dn, attrs in results:
            if dn is None:
                continue
            entries.append({
                'name': sanitize_display_name(attrs.get('cn', [b''])[0].decode('utf-8')),
                'email': attrs.get('mail', [b''])[0].decode('utf-8'),
                'department': attrs.get('department', [b''])[0].decode('utf-8')
            })

        return jsonify({'count': len(entries), 'results': entries[:50]}), 200

    except ldap.LDAPError as e:
        logging.error(f"LDAP search error: {e}")
        return jsonify({'error': 'Directory service unavailable'}), 503

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
